const STORE='ahmed-os-interview-progress-v1';
let quick=false;
function getProgress(){try{return JSON.parse(localStorage.getItem(STORE)||'{}')}catch{return{}}}
function setStatus(id,value){const p=getProgress();p[id]=value;localStorage.setItem(STORE,JSON.stringify(p));render()}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function paragraphs(s,cls=''){return '<div class="'+cls+'">'+String(s||'').split(/\n\n+/).map(x=>'<p>'+escapeHtml(x)+'</p>').join('')+'</div>'}
function highlightCode(s){return escapeHtml(s).replace(/\b(await|async|class|interface|public|private|return|var|const|let|new|if|else|using|int|string|decimal|void|record|readonly|SELECT|FROM|WHERE|JOIN|GROUP|BY|ORDER|CREATE|INDEX|ON|AS|BEGIN|END)\b/g,'<span class="code-keyword">$1</span>').replace(/(&quot;[^\n]*?&quot;|&#39;[^\n]*?&#39;)/g,'<span class="code-string">$1</span>')}
function render(){const p=getProgress(),search=document.getElementById('search').value.trim().toLowerCase(),day=document.getElementById('day').value,status=document.getElementById('status').value;
 const mastered=topics.filter(t=>p[t.id]==='mastered').length;document.getElementById('counter').textContent=mastered+' / '+topics.length+' mastered';document.getElementById('progress').style.width=100*mastered/topics.length+'%';
 const matched=topics.filter(t=>(day==='all'||String(t.day)===day)&&(status==='all'||(p[t.id]||'new')===status)&&[t.title,t.category,t.concept,t.question,t.answer,t.detailed,...t.followUps.map(f=>f.question)].join(' ').toLowerCase().includes(search));
 const groups=new Map();for(const t of matched){const key='Day '+t.day+' · '+t.category;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(t)}
 document.getElementById('cards').innerHTML=matched.length?[...groups].map(([name,items])=>'<section class="topic-group"><div class="topic-heading"><h2>'+escapeHtml(name)+'</h2><span class="chip">'+items.length+' concepts · '+items.length*3+' questions</span></div>'+items.map(t=>'<article class="card"><details class="concept"><summary><strong>'+escapeHtml(t.title)+'</strong><span class="chip">'+escapeHtml(p[t.id]||'Not started')+'</span></summary><section class="concept-body"><h3>Concept explained</h3>'+paragraphs(t.concept)+(!quick?paragraphs(t.arabic,'arabic'):'')+'<section class="question"><h3>Interview question</h3><b>'+escapeHtml(t.question)+'</b><div class="answer-short"><small>SHORT ANSWER · English</small><p>'+escapeHtml(t.answer)+'</p></div>'+(!quick?'<details><summary>Detailed explanation · English + عربي</summary>'+paragraphs(t.detailed,'answer-detailed')+paragraphs(t.arabic,'arabic')+'<p><strong>Common mistake:</strong> '+escapeHtml(t.commonMistake)+'</p></details>':'')+'<h3>Follow-up questions</h3>'+t.followUps.map((f,i)=>'<details><summary>'+(i+1)+'. '+escapeHtml(f.question)+'</summary><div class="answer-detailed"><p>'+escapeHtml(f.answer)+'</p></div></details>').join('')+(!quick?'<details><summary>Code example & explanation</summary><div class="code-panel"><div class="code-header"><span>CODE EXAMPLE</span><button type="button" class="copy-code" data-code="'+t.id+'">Copy code</button></div><pre><code>'+highlightCode(t.code)+'</code></pre></div><p class="muted">Try to explain each line, expected result, and one edge case before copying.</p></details>':'')+'</section><div class="actions"><label class="muted" for="s-'+t.id+'">Progress</label><select id="s-'+t.id+'" data-id="'+t.id+'"><option value="new">Not started</option><option value="learning">Learning</option><option value="review">Needs review</option><option value="mastered">Mastered</option></select></div></section></details></article>').join('')+'</section>').join(''):'<p class="empty">No matching questions.</p>';
 document.querySelectorAll('select[data-id]').forEach(el=>{el.value=p[el.dataset.id]||'new';el.onchange=()=>setStatus(el.dataset.id,el.value)});
}
document.getElementById('cards').addEventListener('click',async e=>{const b=e.target.closest('.copy-code');if(!b)return;const t=topics.find(x=>x.id===b.dataset.code);if(!t)return;try{await navigator.clipboard.writeText(t.code);b.textContent='Copied ✓';setTimeout(()=>b.textContent='Copy code',1600)}catch{b.textContent='Copy unavailable'}});
for(const id of ['search','day','status'])document.getElementById(id).addEventListener(id==='search'?'input':'change',render);
document.getElementById('quick').onclick=function(){quick=!quick;this.classList.toggle('active',quick);this.setAttribute('aria-pressed',String(quick));render()};render();